mapper.select:
SELECT id, type, content, image_url, reference_text, explanation, blank_reveal_count,
       status, department_id, source_number, created_by, created_at, updated_at
FROM problems WHERE id = #{id}

SELECT p.id, p.type, p.content, p.status, p.department_id, d.name AS department_name, p.created_at, COALESCE(array_agg(DISTINCT t.name) FILTER (WHERE t.name IS NOT NULL), '{}') AS tags FROM problems p JOIN departments d ON d.id = p.department_id LEFT JOIN problem_tags pt ON pt.problem_id = p.id LEFT JOIN tags t ON t.id = pt.tag_id
GROUP BY p.id, d.name
ORDER BY p.created_at DESC, p.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT p.id, p.type, p.content, p.status, p.department_id, d.name AS department_name, p.created_at, COALESCE(array_agg(DISTINCT t.name) FILTER (WHERE t.name IS NOT NULL), '{}') AS tags FROM problems p JOIN departments d ON d.id = p.department_id LEFT JOIN problem_tags pt ON pt.problem_id = p.id LEFT JOIN tags t ON t.id = pt.tag_id
AND p.department_id = #{departmentId}
GROUP BY p.id, d.name
ORDER BY p.created_at DESC, p.id DESC LIMIT #{limit}
